import { build } from "esbuild";
import { mkdir, readFile, writeFile } from "node:fs/promises";

const result = await build({ entryPoints: ["scripts/codemirror-entry.ts"], bundle: true, format: "iife", platform: "browser", minify: true, write: false });
const source = result.outputFiles[0].text;
await mkdir("lib/editor", { recursive: true });
await writeFile("lib/editor/codemirror-bundle.ts", `// Generated by pnpm build:editor. Do not edit by hand.\nexport const codeMirrorBundle = ${JSON.stringify(source)};\n`);
console.log(`CodeMirror bundle generated (${source.length} bytes)`);
